           h("div", { className: "actions" }, [SubmitButton()]),
           status,
         ]);

         return h("main", { className: "app-shell" }, [
           h("section", { className: "card", "aria-labelledby": "page-title" }, [
             h("h1", { id: "page-title", textContent: "Terms consent" }),
             h("p", {
               className: "subtitle",
               textContent: "Please confirm your agreement before continuing.",
             }),
             form,
           ]),
         ]);
       }

       document.getElementById("root").appendChild(App());
     </script>
